pub fn r#make_call(&mut self, r#args: &[NodeId], r#extra: Call) -> (NodeId,NodeId,) {
for &id in r#args { self.check(id); }
let result = unsafe { self.proc.r#make_call(r#args,r#extra,) };
self.register(result.0);
self.register(result.1);
result
}
